def split_prices(digits, k, cap):
    n = len(digits)
    width = len(str(cap))

    def pieces(pos):
        # every end position of a valid price starting at pos
        if digits[pos] == '0':
            return
        for end in range(pos + 1, min(pos + width, n) + 1):
            if int(digits[pos:end]) > cap:
                return
            yield end

    can = [[False] * (n + 1) for _ in range(k + 1)]
    can[0][n] = True
    for left in range(1, k + 1):
        for pos in range(n):
            can[left][pos] = any(can[left - 1][end] for end in pieces(pos))

    out, parts = [], []

    def place(pos):
        left = k - len(parts)
        if left == 0:
            out.append(parts[:])
            return
        for end in pieces(pos):
            if can[left - 1][end]:
                parts.append(int(digits[pos:end]))
                place(end)
                parts.pop()

    if can[k][0]:
        place(0)
    return out
